import sys


def max_min(a, n, res):
    # res[0]、res[1] 相当于 C 里的两个 int * 输出参数
    res[0] = res[1] = a[0]
    for i in range(1, n):
        if a[i] > res[0]:
            res[0] = a[i]
        if a[i] < res[1]:
            res[1] = a[i]


def main():
    data = sys.stdin.read().split()
    if len(data) < 8:
        return
    a = [int(v) for v in data[:8]]
    res = [0, 0]
    max_min(a, 8, res)
    print(res[0], res[1])


main()

指-36.solution:
import sys


def less_than(x, y):
    return x < y


def sort(a, cmp):
    n = len(a)
    for i in range(n - 1):
        best = i
        for j in range(i + 1, n):
            if cmp(a[j], a[best]):
                best = j
        if best != i:
            a[i], a[best] = a[best], a[i]


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    if n <= 0 or len(data) < n + 1:
        return
    a = [int(v) for v in data[1:1 + n]]
    sort(a, less_than)
    print(' '.join(str(v) for v in a))


main()

