import sys


def remove_char(s, c):
    q = 0
    for p in range(len(s)):
        if s[p] != c:
            s[q] = s[p]
            q += 1
    del s[q:]           # 相当于在 q 处补 '\0'


def main():
    lines = sys.stdin.read().split('\n')
    if len(lines) < 2:
        return
    s = list(lines[0].rstrip('\r'))
    c = lines[1].strip()[:1]
    if not c:
        return
    remove_char(s, c)
    print(''.join(s))


main()

