import sys


def cmp_int(base, off_a, off_b):
    # 只拿到两个元素的字节偏移，自己按 4 字节小端整数解出来比较
    a = int.from_bytes(base[off_a:off_a + 4], 'little', signed=True)
    b = int.from_bytes(base[off_b:off_b + 4], 'little', signed=True)
    return (a > b) - (a < b)


def swap_bytes(base, off_x, off_y, size):
    for k in range(size):
        t = base[off_x + k]
        base[off_x + k] = base[off_y + k]
        base[off_y + k] = t


def sort(base, n, size, cmp):
    for i in range(n - 1):
        best = i
        for j in range(i + 1, n):
            if cmp(base, j * size, best * size) < 0:
                best = j
        if best != i:
            swap_bytes(base, i * size, best * size, size)


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    if n <= 0 or len(data) < n + 1:
        return

    size = 4
    base = bytearray(size * n)      # 相当于 void *base 指向的一块内存
    for i in range(n):
        v = int(data[1 + i]) & 0xFFFFFFFF
        base[i * size:(i + 1) * size] = v.to_bytes(size, 'little')

    sort(base, n, size, cmp_int)

    out = [str(int.from_bytes(base[i * size:(i + 1) * size], 'little', signed=True))
           for i in range(n)]
    print(' '.join(out))


main()

